contract InvMutTest {
    C c;
    uint counter;

    constructor(C _c) { c = _c; }

    function run(address from, address to, address[] memory tos, uint v) public {
        require(tos.length > 0);
        counter = 0;
        bool ok = c.transfer(from, address(this), tos, v);
        assert(ok && counter == tos.length);
    }

    fallback() external payable {
        counter++;
        assembly {
            mstore(0x00, 1)
            return(0x1c, 0x20)
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address[] memory _tos) public {
        require(_tos.length == 0 || caddressOk(_tos));
        bool reverted;
        bool ok;
        if (_tos.length == 0) {
            try c.transfer(address(this), address(this), _tos, 1) { reverted = false; } catch { reverted = true; }
            assert(reverted);
        } else {
            address[] memory tos = _tos;
            try c.transfer(address(this), address(this), tos, 1) returns (bool r) { reverted = false; ok = r; } catch { reverted = true; }
            assert(!reverted && ok);
        }
    }
    function caddressOk(address[] memory) internal pure returns (bool) { return true; }
    fallback() external {}
}

